<script lang="ts">
import {onMount} from 'svelte';
import {invoke} from '@tauri-apps/api/core';
import {listen} from '@tauri-apps/api/event';
import UiIcon from './UiIcon.svelte';
import PluginIcon from './PluginIcon.svelte';
import HudModuleSettings from './HudModuleSettings.svelte';
import HudWidgets from './HudWidgets.svelte';
import HudInGameMenu from './HudInGameMenu.svelte';
import {hudMetricState} from './hud_data';
import type {OverlaySnapshot} from './launcher_extensions';
import{openHudLink}from './hud_links';
import CrosshairOverlay from './CrosshairOverlay.svelte';
import CrosshairStudio from './CrosshairStudio.svelte';
import {HUD_PRESETS,normalizeHudProfile,setAllPlugins,type HudPreset,HUD_ANCHORS,applyHudPreset,deliveryHelp,LAUNCHER_PLUGINS,PLUGIN_CATEGORIES,defaultHudProfile,type HudProfile,type HudModuleId,type PluginWorkspace,type PluginCategory} from './launcher_plugins';
let profile=$state<HudProfile>(defaultHudProfile()),saved=$state(''),profilePath=$state('');
let selected=$state<HudModuleId>('fps'),category=$state<PluginCategory|'all'>('all'),search=$state('');
let companionAvailable=$state(false),bridgeAvailable=$state(false);
let liveFrame=$state<OverlaySnapshot|null>(null);
let previewImage=$state(''),previewLabel=$state(''),customPreview=$state(false),previewBusy=$state(false);
async function refreshPreview(){
 try{const value=await invoke<{data_url:string;label:string;custom:boolean}>('get_hud_preview');previewImage=value.data_url;previewLabel=value.label;customPreview=value.custom;}
 catch{previewLabel='Elige una captura PNG tuya para este equipo.';}
}
async function pickPreview(event:Event){
 const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file)return;
 if(file.size>20*1024*1024){error='La captura debe ocupar menos de 20 MB.';input.value='';return;}
 previewBusy=true;error='';
 try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('No se pudo leer la captura.'));reader.readAsDataURL(file);});await invoke('set_hud_preview',{imageBase64:data});await refreshPreview();}
 catch(problem){error=String(problem);}finally{previewBusy=false;input.value='';}
}
async function latestPreview(){previewBusy=true;try{await invoke('set_hud_preview',{imageBase64:''});await refreshPreview();}catch(problem){error=String(problem);}finally{previewBusy=false;}}

let menuPreview=$state<HTMLDialogElement>();
let loading=$state(true),saving=$state(false),message=$state(''),error=$state(''),overlay=$state(false),overlayBusy=$state(false);
let selectedPlugin=$derived(LAUNCHER_PLUGINS.find(plugin=>plugin.id===selected)!);
let selectedModule=$derived(profile.modules.find(module=>module.id===selected)!);
let enabledCount=$derived(profile.modules.filter(module=>module.enabled).length);
let dirty=$derived(JSON.stringify(profile)!==saved);
let filtered=$derived(LAUNCHER_PLUGINS.filter(plugin=>(category==='all'||category===plugin.category)&&(plugin.name+' '+plugin.description).toLocaleLowerCase().includes(search.toLocaleLowerCase())));
let page=$state(1);const pageSize=12;let pageCount=$derived(Math.max(1,Math.ceil(filtered.length/pageSize)));let pageRows=$derived(filtered.slice((page-1)*pageSize,page*pageSize));
$effect(()=>{search;category;page=1;});

onMount(()=>{
let alive=true;
let stopProfile:(()=>void)|undefined;
void listen<HudProfile>('tp-hud-profile',event=>{if(alive&&!dirty){profile=normalizeHudProfile(event.payload);saved=JSON.stringify(profile);}}).then(stop=>{if(alive)stopProfile=stop;else stop();});
void invoke<PluginWorkspace>('get_launcher_plugins').then(workspace=>{if(alive){profile=normalizeHudProfile(workspace.profile);companionAvailable=workspace.companion_available;bridgeAvailable=workspace.bridge_available;profilePath=workspace.profile_path;saved=JSON.stringify(profile);}}).catch(problem=>{if(alive)error=String(problem);}).finally(()=>{if(alive)loading=false;});
const syncOverlay=()=>void invoke<boolean>('get_launcher_overlay').then(value=>{if(alive)overlay=value;}).catch(()=>{});
syncOverlay();window.addEventListener('focus',syncOverlay);
void refreshPreview();
const syncFrame=()=>{if(document.hasFocus())void invoke<OverlaySnapshot>('get_overlay_snapshot').then(value=>{if(alive)liveFrame=value;}).catch(()=>{});};
syncFrame();const frameTimer=window.setInterval(syncFrame,1000);window.addEventListener('focus',syncFrame);

return()=>{alive=false;stopProfile?.();window.removeEventListener('focus',syncOverlay);window.removeEventListener('focus',syncFrame);window.clearInterval(frameTimer);};
});
async function save(){if(saving||loading)return;saving=true;message='';error='';try{profile=normalizeHudProfile(await invoke<HudProfile>('save_launcher_plugins',{profile:$state.snapshot(profile)}));saved=JSON.stringify(profile);message='Selección guardada. TP Companion y los optimizadores se prepararán al iniciar una instalación compatible.';}catch(problem){error=String(problem);}finally{saving=false;}}
async function openFolder(){try{await invoke('open_launcher_plugins_folder');}catch(problem){error=String(problem);}}
async function toggleOverlay(){if(overlayBusy)return;overlayBusy=true;error='';try{overlay=await invoke<boolean>('set_launcher_overlay',{enabled:!overlay});profile.native_overlay=overlay;if(overlay&&companionAvailable)profile.companion_enabled=true;await save();if(overlay)message='HUD preparado. Abre Minecraft y pulsa Shift derecho o F8 para editarlo. Si el juego ya estaba abierto, reinícialo para conectar FPS y posición.';}catch(problem){error=String(problem);}finally{overlayBusy=false;}}
function preset(kind:HudPreset){profile=applyHudPreset($state.snapshot(profile),kind);selected=profile.modules.find(module=>module.enabled)!.id;message='';}
</script>

<section class="plugins-workspace" aria-busy={loading}>
<header class="plugins-heading"><div><span class="eyebrow">PERSONALIZA TU PARTIDA</span><h2>Plugins, HUDs y overlays</h2><p>Organiza tus herramientas y prepara cada instalación a tu manera.</p></div><button onclick={()=>menuPreview?.showModal()}><UiIcon name="sliders" size={16}/>Abrir editor de HUD</button><span class="selection-count">{enabledCount} seleccionados · {LAUNCHER_PLUGINS.length} módulos</span></header>
<section class="native-overlay"><span class="overlay-emblem"><UiIcon name="grid" size={24}/></span><div><h3>Overlay nativo TP</h3><p>Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).</p><small>Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.</small></div><button class:active={overlay} disabled={overlayBusy||loading||saving} onclick={toggleOverlay}><UiIcon name={overlay?'eye-off':'eye'} size={17}/>{overlayBusy?'Aplicando…':overlay?'Desactivar HUD universal':'Activar HUD universal'}</button></section>
<section class="companion-note"><UiIcon name="plugins" size={20}/><div><strong>Integración extendida · TP Companion</strong><p>HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.</p><label class="companion-opt-in"><input type="checkbox" bind:checked={profile.companion_enabled} disabled={loading||saving||!companionAvailable}/>Instalar el complemento TP al preparar una instancia compatible</label><small>{companionAvailable?'Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.':'El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.'}</small></div></section>
<section class="bridge-status"><div><h3><UiIcon name="link" size={17}/>Datos del juego</h3><p>{bridgeAvailable?'El conector está listo. Activa el HUD antes de abrir Minecraft.':'Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.'}</p><small>{liveFrame?.message||'Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.'}</small></div><dl><dt>FPS</dt><dd>{liveFrame?.game_fps!=null?Math.round(liveFrame.game_fps):hudMetricState('fps',liveFrame).short}</dd><dt>Coordenadas</dt><dd>{hudMetricState('coordinates',liveFrame).short}</dd><dt>Conexión</dt><dd>{liveFrame?.telemetry?.source||'Esperando partida'}</dd></dl></section>
{#if error}<p class="plugin-message error" role="alert">{error}</p>{/if}{#if message}<p class="plugin-message" role="status">{message}</p>{/if}
<p>Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.</p><div class="bulk"><button onclick={()=>setAllPlugins(profile,true)}>Activar todos los plugins</button><button onclick={()=>setAllPlugins(profile,false)}>Desactivar todos</button></div><div class="plugins-tools"><label class="plugin-search"><UiIcon name="search" size={16}/><input type="search" bind:value={search} placeholder="Buscar herramienta o función…" aria-label="Buscar plugin"/></label><nav aria-label="Categorías de plugins"><button class:active={category==='all'} onclick={()=>category='all'}>Todos</button>{#each PLUGIN_CATEGORIES as item}<button class:active={category===item.id} onclick={()=>category=item.id}><UiIcon name={item.icon} size={14}/>{item.name}</button>{/each}</nav></div>
<div class="plugin-grid">{#each pageRows as plugin (plugin.id)}{@const module=profile.modules.find(item=>item.id===plugin.id)!}<article class="plugin-card" class:selected={selected===plugin.id}><button class="plugin-detail" onclick={()=>selected=plugin.id} aria-pressed={selected===plugin.id}><span class="plugin-slot"><PluginIcon id={plugin.id} size={26}/></span><span><strong>{plugin.name}</strong><small>{deliveryHelp(plugin.id)}</small></span></button><p>{plugin.description}</p>{#if plugin.project}<button onclick={()=>void openHudLink(plugin.project!).catch(problem=>error=String(problem))}>Proyecto en Modrinth ↗</button>{/if}<label class="module-toggle"><input type="checkbox" bind:checked={module.enabled} onchange={()=>{if(module.id==='no_fog')profile.fog.enabled=module.enabled;}} disabled={loading||saving}/><span class="switch" aria-hidden="true"></span><span>{module.enabled?'Incluir en mi perfil':'Sin incluir'}</span></label></article>{/each}</div>
<nav class="catalog-pages" aria-label="Páginas del catálogo de módulos"><button disabled={page<=1} onclick={()=>page--}>Anterior</button><span>{page} / {pageCount} · {filtered.length} módulos</span><button disabled={page>=pageCount} onclick={()=>page++}>Siguiente</button></nav>{#if !filtered.length}<p class="empty">No hay herramientas con esa búsqueda.</p>{/if}
<details class="crosshair-studio"><summary>Estudio de mira e impactos</summary><CrosshairStudio bind:profile/></details><div class="designer-layout"><section class="hud-designer"><header class="preview-heading"><div><h3>Vista previa del perfil</h3><small>Datos de ejemplo · no son estadísticas de una partida</small></div><button onclick={()=>menuPreview?.showModal()}><UiIcon name="grid" size={15}/>Probar menú In-Game</button></header><div class="hud-scene" style:background-image={previewImage?`linear-gradient(#0001,#0001),url("${previewImage}")`:undefined} style={'--hud-scale:'+profile.scale+';--hud-opacity:'+profile.opacity} class:no-background={!profile.background}><CrosshairOverlay {profile} preview/><HudWidgets {profile} preview editing onchange={()=>{}}/></div><div class="preview-options"><label class="capture-button"><UiIcon name="image" size={15}/>{previewBusy?'Preparando…':'Elegir captura propia'}<input type="file" accept="image/png" onchange={pickPreview} disabled={previewBusy}/></label><button onclick={latestPreview} disabled={previewBusy}><UiIcon name="refresh" size={15}/>{customPreview?'Usar última captura F2':'Actualizar captura F2'}</button><small>{previewLabel} · Solo en este equipo</small></div><div class="presets"><span>Empezar con:</span>{#each HUD_PRESETS as p}<button disabled={loading||saving} onclick={()=>preset(p.id)}>{p.name}</button>{/each}</div></section>
<section class="plugin-settings"><header><h3>{selectedPlugin.name}</h3><small>{deliveryHelp(selected)}</small></header><div class="settings-fields"><HudModuleSettings bind:profile {selected}/><label>Nombre del perfil<input bind:value={profile.name} maxlength="60" disabled={loading||saving}/></label><label class="check-line"><input type="checkbox" bind:checked={profile.auto_borderless} disabled={loading||saving}/>Pantalla completa sin bordes al activar el HUD</label><button class="save-hud" onclick={save} disabled={loading||saving||!profile.name.trim()||!dirty}><UiIcon name="save" size={16}/>{saving?'Guardando…':'Guardar selección y diseño'}</button><small>{dirty?'Cambios sin guardar':'Tu perfil está guardado'}</small><button class="folder-link" onclick={openFolder}><UiIcon name="folder" size={15}/>Abrir carpeta de plugins</button>{#if profilePath}<small class="profile-path" title={profilePath}>{profilePath}</small>{/if}</div></section></div>
</section>

<dialog bind:this={menuPreview} class="menu-preview"><div class="preview-backdrop" style:background-image={previewImage?`linear-gradient(#0002,#0002),url("${previewImage}")`:undefined}><CrosshairOverlay {profile} preview/><HudWidgets {profile} preview editing onchange={()=>{}}/><HudInGameMenu bind:profile onchange={()=>{}} onlayout={()=>menuPreview?.close()} onclose={()=>menuPreview?.close()} preview message="Vista previa: guarda el perfil para aplicar los cambios." fpsStatus="Datos de ejemplo del diseñador"/></div></dialog>
<style>
.catalog-pages{display:flex;align-items:center;justify-content:center;gap:15px;font-size:12px}.crosshair-studio{padding:18px;border:1px solid #a855f744;background:#0b0b0fcc}.crosshair-studio>summary{cursor:pointer;font-size:14px;margin-bottom:16px}

.bridge-status{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px;border:1px solid #a855f744;background:#15101fd9}.bridge-status h3{display:flex;align-items:center;gap:8px;margin:0 0 8px;font-size:.88rem}.bridge-status p,.bridge-status small{font-size:.75rem;line-height:1.7;color:#b7a5c8}.bridge-status dl{display:grid;grid-template-columns:auto auto;gap:9px 18px;min-width:220px;font-size:.7rem}.bridge-status dt{color:#9f8ead}.bridge-status dd{margin:0;color:#e1c8f4;text-align:right}.preview-options{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.capture-button{display:inline-flex;align-items:center;gap:7px;border:1px solid #a855f755;background:#20172e;padding:8px 11px;cursor:pointer;font-size:.7rem}.capture-button input{display:none}.preview-options small{width:100%;font-size:.65rem;color:#a296b0}.preview-options button{display:inline-flex;align-items:center;gap:7px;font-size:.7rem}@media(max-width:800px){.bridge-status{align-items:start;flex-direction:column}}

.plugins-workspace{display:grid;gap:19px;min-width:0;color:#e9e2f2}.plugins-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.plugins-heading>div{flex:1;min-width:250px}.eyebrow{font-size:.55rem;letter-spacing:.12em;color:var(--primary,#a855f7)}h2{font-size:1.6rem;margin:10px 0}h3{font-size:.94rem;margin:0 0 7px}p{font-size:.76rem;color:#a89ab8;line-height:1.7;margin:0}small{font-size:.63rem;color:#9685a8;line-height:1.6}.selection-count{white-space:nowrap;padding:9px 12px;border:1px solid #a855f73b;color:#c9a6ed;font-size:.67rem}.native-overlay{display:flex;align-items:center;gap:16px;padding:20px;border:1px solid #a855f73a;background:#a855f70a}.native-overlay>div{flex:1}.native-overlay p{font-size:.73rem}.native-overlay small{display:block;margin-top:8px}.overlay-emblem{width:45px;height:45px;display:grid;place-items:center;color:var(--primary,#a855f7);background:#a855f712;flex-shrink:0}.companion-note{display:flex;align-items:start;gap:12px;border-left:2px solid #bca574;border-top:1px solid #bca57427;border-bottom:1px solid #bca57427;background:#bca57407;padding:14px 17px}.companion-note :global(svg){color:#bca574;flex-shrink:0}.companion-note p{font-size:.7rem}.companion-note strong{font-size:.8rem;color:#d7c0ed}.companion-note small{display:block;font-size:.6rem;margin-top:8px}.companion-opt-in{display:flex;gap:8px;align-items:center;font-size:.7rem;color:#cebbdf;margin-top:12px}.companion-opt-in input{accent-color:var(--primary,#a855f7)}.plugins-tools{display:flex;gap:13px;align-items:center;flex-wrap:wrap}.plugin-search{display:flex;align-items:center;gap:8px;min-width:200px;flex:1;border:1px solid #ffffff20;padding:0 11px;background:#0b0b0f}.plugin-search input{border:0;background:none;color:#e6dcef;padding:11px 0;width:100%;font:inherit;font-size:.74rem;min-width:0}.plugins-tools nav{display:flex;gap:6px;flex-wrap:wrap}button{display:inline-flex;align-items:center;justify-content:center;gap:7px;background:#ffffff05;border:1px solid #ffffff20;color:#d4c4e5;font:inherit;font-size:.7rem;padding:9px 12px;cursor:pointer}button:hover:not(:disabled),button.active{background:#a855f715;border-color:var(--primary,#a855f7);color:#d5b3f4}button:disabled{opacity:.4;cursor:default}button:focus-visible,input:focus-visible{outline:2px solid var(--primary,#a855f7);outline-offset:3px}.plugin-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.plugin-card{display:flex;flex-direction:column;gap:12px;padding:16px;border:1px solid #ffffff14;background:rgba(var(--bg-base-rgb,22,22,30),.65);min-width:0}.plugin-card.selected{border-color:#a855f760}.plugin-detail{border:0;background:none;padding:0;justify-content:start;text-align:left;gap:11px}.plugin-detail>span:last-child{min-width:0;flex:1}.plugin-detail strong{display:block;font-size:.79rem;overflow-wrap:anywhere}.plugin-detail small{display:block;font-size:.56rem;margin-top:4px}.plugin-slot{width:38px;height:38px;display:grid;place-items:center;flex-shrink:0;background:#0003;border:1px solid #ffffff10}.plugin-card p{font-size:.69rem;flex:1}.module-toggle{display:flex;align-items:center;gap:8px;font-size:.66rem;color:#a793bc;cursor:pointer}.module-toggle input{position:absolute;opacity:0;width:1px;height:1px}.switch{display:block;width:29px;height:16px;background:#3b3247;border:1px solid #ffffff15;position:relative;flex-shrink:0}.switch:after{content:'';position:absolute;left:2px;top:2px;width:10px;height:10px;background:#b4a5c3;transition:transform .15s}.module-toggle input:checked+.switch{background:#a855f7}.module-toggle input:checked+.switch:after{transform:translateX(13px);background:white}.module-toggle input:focus-visible+.switch{outline:2px solid #d946ef;outline-offset:3px}.designer-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(250px,1fr);gap:16px}.hud-designer,.plugin-settings{min-width:0;border:1px solid #ffffff17;background:#16161e80}.hud-designer>header,.plugin-settings>header{padding:17px;border-bottom:1px solid #ffffff12}.hud-scene{position:relative;height:340px;margin:12px;overflow:hidden;background:linear-gradient(#303749 0 60%,#262536 60%);border:1px solid #ffffff13}.hud-scene:before{content:'';position:absolute;inset:40% 0 25%;background:#1d1d2b;clip-path:polygon(0 45%,15% 45%,15% 10%,30% 10%,30% 40%,50% 40%,50% 0,70% 0,70% 30%,100% 30%,100% 100%,0 100%)}.presets{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:0 12px 14px}.presets>span{font-size:.64rem;color:#9f8eb2}.presets button{font-size:.62rem;padding:7px 9px}.settings-fields{display:grid;gap:16px;padding:17px}.settings-fields label{display:grid;gap:8px;font-size:.69rem;color:#aa97bf}.settings-fields input:not([type=range],[type=checkbox]){width:100%;box-sizing:border-box;min-width:0;background:#0b0b0f;color:#e4d9ef;border:1px solid #ffffff22;padding:10px;font:inherit;font-size:.72rem;color-scheme:dark}input[type=checkbox]{accent-color:var(--primary,#a855f7)}.settings-fields .check-line{display:flex;align-items:center;gap:8px}.save-hud{background:#a855f715;border-color:#a855f750}.folder-link{font-size:.66rem}.profile-path{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.53rem}.plugin-message{border:1px solid #7dbba744;background:#7dbba70a;padding:13px;color:#b1d6c9;font-size:.74rem;line-height:1.7}.plugin-message.error{border-color:#cfaa7044;background:#cfaa7008;color:#d5bf99}.empty{text-align:center;padding:24px;border:1px dashed #ffffff20;color:#a793bc}@media(max-width:1200px){.plugin-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.native-overlay{flex-wrap:wrap}.native-overlay>button{width:100%}.designer-layout{grid-template-columns:1fr}}@media(max-width:640px){.plugin-grid{grid-template-columns:1fr}.plugins-heading{align-items:start;flex-wrap:wrap}.plugins-tools nav{width:100%}.plugins-tools nav button{flex:1}.native-overlay{padding:15px}.hud-scene{height:310px}.selection-count{font-size:.6rem}}@media(prefers-reduced-motion:reduce){.switch:after{transition:none}}
.hud-scene{height:auto;aspect-ratio:16/9;min-height:260px;background:linear-gradient(#00000008,#00000012),url("/images/hud-preview.svg") center/cover no-repeat}.hud-scene:before{display:none}.preview-heading{display:flex;justify-content:space-between;align-items:center;gap:14px}.preview-heading button{font-size:.65rem;white-space:nowrap}.menu-preview{padding:0;border:1px solid #a855f750;width:min(1240px,calc(100vw - 26px));height:min(780px,calc(100vh - 26px));max-width:none;max-height:none;background:#0b0b0f;color:#eee;overflow:hidden}.menu-preview::backdrop{background:#030008bb;backdrop-filter:blur(6px)}.preview-backdrop{position:relative;display:grid;place-items:center;width:100%;height:100%;background:linear-gradient(#0002,#0002),url("/images/hud-preview.svg") center/cover no-repeat}.preview-backdrop :global(.editor){z-index:1;width:calc(100% - 28px);max-height:calc(100% - 28px)}</style>
